  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

function matchesSearch(value, query) {
  const normalize = text => text.replace(/[ \t]+/g, ' ')
    .replace(/[A-Z]/g, letter => letter.toLowerCase());
  return normalize(value).includes(normalize(query));
}

function projectListQuery(filter, search) {
  return new URLSearchParams({ filter, search }).toString();
}

function projectsPage(error = '', filter = 'Active', search = '', importFields = { json: '', name: '' }) {
  const projects = listProjects.all(filter === 'Archived' ? 1 : 0)
    .filter(project => matchesSearch(project.name, search));
  const query = escapeHtml(projectListQuery(filter, search));
  return page('Projects', `
    <p class="eyebrow">Your workspace</p>
    <h1>Workboard</h1>
    <form method="get" action="/directory"><button type="submit">Task directory</button></form>
    <form class="create-form" method="post" action="/projects?${query}">
      ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
      <label for="project-name">Project name</label>
      <div class="controls">
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Create project</button>
      </div>
    </form>
    <form class="create-form" method="post" action="/projects/import?${query}">
      <label for="project-json">Project JSON</label>
      <textarea id="project-json" name="json" rows="6">\n${escapeHtml(importFields.json)}</textarea>
      <label for="imported-project-name">Imported project name</label>
      <div class="controls">
        <input id="imported-project-name" name="name" type="text" value="${escapeHtml(importFields.name)}">
        <button type="submit">Import project</button>
      </div>
    </form>
    <h2>Projects</h2>
    <form method="get" action="/">
      <input type="hidden" name="search" value="${escapeHtml(search)}">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['Active', 'Archived'].map(option => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <form class="create-form" method="get" action="/">
      <input type="hidden" name="filter" value="${filter}">
      <label for="project-search">Project search</label>
      <div class="controls">
        <input id="project-search" name="search" type="text" value="${escapeHtml(search)}">
        <button type="submit">Search projects</button>
      </div>
    </form>
    ${projects.length ? `<ul class="project-list">${projects.map(project => `
      <li class="project-row" data-testid="project-row">
        <div><span class="project-name">${escapeHtml(project.name)}</span>
          <span class="project-summary" data-testid="project-summary">${project.completed}/${project.total} completed</span>
        </div>
        <div class="project-actions">
          <form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form>
          <form method="post" action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}?${query}"><button type="submit">${project.archived ? 'Restore' : 'Archive'} project</button></form>
        </div>
      </li>`).join('')}</ul>` : `<p class="empty">${filter === 'Archived' ? 'No archived projects.' : 'No projects yet. Create a project to get started.'}</p>`}
  `);
}

function html(response, status, content) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' });
  response.end(content);
}

function taskFilterQuery(filter, priorityFilter, dueRange = { from: '', through: '' }, search = '') {
  const query = new URLSearchParams({ filter });
  if (priorityFilter !== 'All') query.set('priorityFilter', priorityFilter);
  if (dueRange.from) query.set('dueFrom', dueRange.from);
  if (dueRange.through) query.set('dueThrough', dueRange.through);
  if (search) query.set('search', search);
  return query.toString();
}

function matchesTask(task, filter, priorityFilter, dueRange, search) {
  return matchesSearch(task.title, search) &&
    (filter === 'Deleted' ? Boolean(task.deleted) : (!task.deleted &&
      (filter === 'All' || Boolean(task.completed) === (filter === 'Completed')))) &&
    (priorityFilter === 'All' || task.priority === priorityFilter) &&
    ((!dueRange.from && !dueRange.through) || (task.due_date !== '' &&
      (!dueRange.from || task.due_date >= dueRange.from) &&
      (!dueRange.through || task.due_date <= dueRange.through)));
}

function directoryQuery(scope, filter, priorityFilter, dueRange, search, order = 'Original') {
  const query = new URLSearchParams(taskFilterQuery(filter, priorityFilter, dueRange, search));
  query.set('scope', scope);
  if (order !== 'Original') query.set('order', order);
  return query.toString();
}

function compareCodePoints(left, right) {
  const leftPoints = Array.from(left, character => character.codePointAt(0));
  const rightPoints = Array.from(right, character => character.codePointAt(0));
  for (let index = 0; index < Math.min(leftPoints.length, rightPoints.length); index++) {
    if (leftPoints[index] !== rightPoints[index]) return leftPoints[index] - rightPoints[index];
  }
  return leftPoints.length - rightPoints.length;
}

function orderDirectoryTasks(tasks, order) {
  // Stable sorting keeps the original owner/task order for equal keys.
  if (order === 'Priority') {
    const rank = { High: 0, Normal: 1, Low: 2 };
    tasks.sort((left, right) => rank[left.priority] - rank[right.priority]);
  } else if (order === 'Due date') {
    tasks.sort((left, right) => {
      if (!left.due_date || !right.due_date) return Number(!left.due_date) - Number(!right.due_date);
      return compareCodePoints(left.due_date, right.due_date);
    });
  } else if (order === 'Title') {
    const fold = title => title.replace(/[A-Z]/g, letter => letter.toLowerCase());
    tasks.sort((left, right) => compareCodePoints(fold(left.title), fold(right.title)));
  }
  return tasks;
}

function directoryTasks(scope, filter, priorityFilter, dueRange, search) {
  return listDirectoryTasks.all(scope === 'Archived' ? 1 : 0)
    .filter(task => matchesTask(task, filter, priorityFilter, dueRange, search));
}

function setDirectoryCompletion(scope, filter, priorityFilter, dueRange, search, completed) {
  if (scope !== 'Active' || filter === 'Deleted') return;
  transaction(() => {
    for (const task of directoryTasks(scope, filter, priorityFilter, dueRange, search)) {
      if (Boolean(task.completed) !== completed) {
        updateTask.run(Number(completed), task.id, task.project_id);
      }
    }
  });
}

function directoryPage(scope, filter, priorityFilter, dueRange, search, error = '', order = 'Original') {
  const tasks = orderDirectoryTasks(directoryTasks(scope, filter, priorityFilter, dueRange, search), order);
  const completedCount = tasks.reduce((count, task) => count + Number(Boolean(task.completed)), 0);
  const readOnly = scope === 'Archived' || filter === 'Deleted';
  const query = escapeHtml(directoryQuery(scope, filter, priorityFilter, dueRange, search, order));
  const completionForm = (action, label, completed) => `
    <form method="post" action="/directory/${action}?${query}">
      <button type="submit"${readOnly || !tasks.some(task => Boolean(task.completed) !== completed) ? ' disabled' : ''}>${label}</button>
    </form>`;
  const fields = {
    scope, filter, priorityFilter, dueFrom: dueRange.from, dueThrough: dueRange.through, search, order,
  };
  const hiddenFields = excluded => Object.entries(fields)
    .filter(([name]) => !excluded.includes(name))
    .map(([name, value]) => `<input type="hidden" name="${name}" value="${escapeHtml(value)}">`).join('');
  const selectForm = (label, name, options) => `
    <form method="get" action="/directory">
      ${hiddenFields([name])}
      <label for="directory-${name}">${label}</label>
      <select id="directory-${name}" name="${name}" onchange="this.form.requestSubmit()">
        ${options.map(option => `<option${fields[name] === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>`;
  return page('Task directory', `
    <form action="/" method="get"><button type="submit">Projects</button></form>
    <h1>Task directory</h1>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    ${selectForm('Project scope', 'scope', ['Active', 'Archived'])}
    ${selectForm('Task filter', 'filter', ['All', 'Open', 'Completed', 'Deleted'])}
    ${selectForm('Priority filter', 'priorityFilter', ['All', ...taskPriorities])}
    ${selectForm('Directory order', 'order', directoryOrders)}
    <form class="create-form" method="get" action="/directory">
      ${hiddenFields(['search'])}
      <label for="directory-search">Directory search</label>
      <div class="controls">
        <input id="directory-search" name="search" type="text" value="${escapeHtml(search)}">
        <button type="submit">Search directory</button>
      </div>
    </form>
    <form class="create-form" method="post" action="/directory/due-range?${escapeHtml(directoryQuery(scope, filter, priorityFilter, dueRange, search, order))}">
      <label for="directory-due-from">Due from</label>
      <input id="directory-due-from" name="dueFrom" type="text" value="${escapeHtml(dueRange.from)}">
      <label for="directory-due-through">Due through</label>
      <input id="directory-due-through" name="dueThrough" type="text" value="${escapeHtml(dueRange.through)}">
      <button type="submit">Apply due range</button>
    </form>
    <div class="controls">
      ${completionForm('complete', 'Complete visible tasks', true)}
      ${completionForm('reopen', 'Reopen visible tasks', false)}
    </div>
    <p data-testid="directory-summary">${completedCount}/${tasks.length} completed</p>
    ${tasks.length ? `<ul class="task-list">${tasks.map(task => `
      <li class="task-row" data-testid="directory-task-row">
        <div class="directory-field" data-testid="directory-task-title">${escapeHtml(task.title)}</div>
        <div class="directory-field" data-testid="directory-project-name">${escapeHtml(task.project_name)}</div>
        <div data-testid="directory-task-completion">${task.completed ? 'Completed' : 'Open'}</div>
        <div data-testid="directory-task-priority">${task.priority}</div>
        <div data-testid="directory-task-due-date">${task.due_date}</div>
        <div class="directory-field" data-testid="directory-task-notes">${escapeHtml(task.notes)}</div>
        <form method="get" action="/projects/${task.project_id}"><button type="submit">Open project</button></form>
      </li>`).join('')}</ul>` : '<p class="empty" id="directory-empty" role="status">No matching tasks</p>'}
    <script>
      document.addEventListener('submit', () => {
        const announcement = document.getElementById('directory-empty');
        if (announcement) announcement.hidden = true;
      });
    </script>
  `);
}

function downloadProject(response, project) {
  const document = {
    format: 'workboard-project',
    version: 1,
    project: {
      name: project.name,
      archived: Boolean(project.archived),
      defaultPriority: project.default_task_priority,
      tasks: listTasks.all(project.id).map(task => ({
        title: task.title,
        completed: Boolean(task.completed),
        priority: task.priority,
        dueDate: task.due_date,
        notes: task.notes.replace(/\r\n?/g, '\n'),
        deleted: Boolean(task.deleted),
      })),
    },
  };
  response.writeHead(200, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Disposition': 'attachment; filename="workboard-project.json"',
    'Cache-Control': 'no-store',
  });
  response.end(JSON.stringify(document, null, 2));
}

function projectPage(project, filter = 'All', error = '', priorityFilter = 'All', dueRange = { from: '', through: '' }, search = '') {
  const destinations = listDestinations.all(project.id);
  const moveDisabled = project.archived || destinations.length === 0;
  const tasks = listTasks.all(project.id)
    .filter(task => matchesTask(task, filter, priorityFilter, dueRange, search));
